{"code":"import random

def generate(rng):
    H = rng.randint(7, 14); W = rng.randint(7, 14)
    g = [[0 for _ in range(W)] for _ in range(H)]
    colors = rng.sample([1,2,3,4,5,6,7,8,9], rng.randint(2, min(5,9)))
    # Place several 3x4 motifs, in either horizontal or vertical orientation,
    # with the long outer segment deliberately missing its middle cells.
    occupied=[]
    for col in colors:
        for attempt in range(30):
            orient=rng.choice(['h','v'])
            if orient=='h':
                h,w=3,4
            else: h,w=4,3
            r=rng.randint(0,H-h); c=rng.randint(0,W-w)
            cells=[]
            if orient=='h':
                cells += [(r,c),(r,c+3)]
                cells += [(r+1,c+1),(r+1,c+2),(r+2,c+1),(r+2,c+2)]
            else:
                cells += [(r,c),(r+3,c)]
                cells += [(r+1,c+1),(r+2,c+1),(r+1,c+2),(r+2,c+2)]
            if all(g[x][y]==0 for x,y in cells):
                for x,y in cells:g[x][y]=col
                occupied.append((r,c,orient,col)); break
    return g"}

